node -e '
const { chromium } = require("/opt/node22/lib/node_modules/playwright");
(async () => {
  const browser = await chromium.launch({
    executablePath: "/usr/bin/google-chrome",
    args: ["--use-gl=angle", "--use-angle=swiftshader", "--enable-webgl", "--ignore-gpu-blocklist"]
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 760 } });
  const errors = [];
  page.on("pageerror", err => errors.push("PAGEERROR: " + err.message));
  page.on("console", msg => {
    if (msg.type() === "error") errors.push("CONSOLE_ERROR: " + msg.text());
  });

  await page.goto("file:///var/tmp/bench/ws-AiHlfEFW/alhambra-ruta-3d.html", { waitUntil: "networkidle" });
  await page.waitForTimeout(900);

  const titleText = await page.textContent("#stop-title");
  const canvasBox = await page.locator("#scene-container canvas").boundingBox();

  // Click through stops 2..8, switch lighting & modes
  await page.click(".wp-chip:nth-child(4)");
  await page.waitForTimeout(250);
  const stop4Title = await page.textContent("#stop-title");

  await page.click(".wp-chip:nth-child(6)");
  await page.waitForTimeout(250);
  const stop6Title = await page.textContent("#stop-title");

  await page.click("[data-time=\"night\"]");
  await page.waitForTimeout(200);

  await page.click("[data-mode=\"orbit\"]");
  await page.waitForTimeout(200);

  await page.click("[data-mode=\"walk\"]");
  await page.waitForTimeout(200);

  console.log(JSON.stringify({ titleText, stop4Title, stop6Title, canvasBox, errors }, null, 2));
  await browser.close();
  process.exit(errors.length ? 1 : 0);
})();
'

